import'package:speech_to_text/speech_to_text.dart';import'package:flutter_tts/flutter_tts.dart';class FunziVoice{final speech=SpeechToText();final tts=FlutterTts();Future<String>listen({String locale='en_KE'})async{final ok=await speech.initialize();if(!ok)throw Exception('Speech recognition unavailable');String text='';await speech.listen(localeId:locale,onResult:(r)=>text=r.recognizedWords);await Future.delayed(const Duration(seconds:6));await speech.stop();return text;}Future<void>speak(String text,{String locale='en-KE'})async{await tts.setLanguage(locale);await tts.setSpeechRate(.45);await tts.speak(text);}Future<void>stop()=>tts.stop();}